style.css:
@-moz-document domain("roblox.com") {
html {
        background: url("https://i.pinimg.com/736x/bf/b3/ad/bfb3ad6ceba804557f58a2bce6b38ff8.jpg") no-repeat center center fixed !important;
        background-size: cover !important;
    }

    body {
        background: transparent !important;
    }

    /* Hauptcontainer durchsichtig machen */
    .rbx-body,
    .container-main,
    .content,
    .rbx-container,
    #container-main {
        background: transparent !important;
    }

    /* Panels leicht abdunkeln für Lesbarkeit */
    .section,
    .card,
    .content,
    .container-main {
        background-color: rgba(0, 0, 0, 0.5) !important;
        border-radius: 10px;
    }
}
